begin;
set local lock_timeout = '30s';

-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 12: wealth planning foundation (D-045). Additive; replaces registry_save_personal in place.
-- Marital regime and tax residence, account balances (BRL/USD/EUR), foreign assets, holdings (legal entities with
-- full/bare/usufruct ownership), private pension (PGBL/VGBL), personal insurance, succession profile, FX rates (BCB PTAX),
-- ITCMD rules per state (admin-validated), Google Meet links, CRM opportunities generated by the analyses.
-- New client tables follow Gate 2: RLS forced, read via can_access_client, writes only through RPCs.

-- ---------------------------------------------------------------- personal: marital regime and tax residence
alter table cw_prod.client_personal_data
  add column marital_status text check (marital_status in ('SINGLE', 'MARRIED', 'STABLE_UNION', 'DIVORCED', 'SEPARATED', 'WIDOWED')),
  add column marital_regime text check (marital_regime in ('COMUNHAO_PARCIAL', 'COMUNHAO_UNIVERSAL', 'SEPARACAO_CONVENCIONAL',
                                                           'SEPARACAO_OBRIGATORIA', 'PARTICIPACAO_AQUESTOS')),
  add column marriage_date date check (marriage_date between date '1900-01-01' and current_date),
  add column prenup boolean,
  add column tax_residence char(2) not null default 'BR' check (tax_residence ~ '^[A-Z]{2}$');

create or replace function cw_prod.registry_save_personal(p_client uuid, p_data jsonb, p_address jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare v_addr uuid;
begin
  perform cw_prod_private.require_client(p_client);
  insert into cw_prod.client_personal_data as d (client_id, full_name, cpf, birth_date, email, phone, profession, profession_code,
                                               marital_status, marital_regime, marriage_date, prenup, tax_residence)
  values (p_client, p_data ->> 'full_name', nullif(p_data ->> 'cpf', ''), (p_data ->> 'birth_date')::date,
          nullif(p_data ->> 'email', ''), nullif(p_data ->> 'phone', ''), nullif(p_data ->> 'profession', ''),
          nullif(p_data ->> 'profession_code', ''), nullif(p_data ->> 'marital_status', ''), nullif(p_data ->> 'marital_regime', ''),
          nullif(p_data ->> 'marriage_date', '')::date, (p_data ->> 'prenup')::boolean, coalesce(nullif(p_data ->> 'tax_residence', ''), 'BR'))
  on conflict (client_id) do update set full_name = excluded.full_name, cpf = excluded.cpf, birth_date = excluded.birth_date,
    email = excluded.email, phone = excluded.phone, profession = excluded.profession, profession_code = excluded.profession_code,
    marital_status = excluded.marital_status, marital_regime = excluded.marital_regime, marriage_date = excluded.marriage_date,
    prenup = excluded.prenup, tax_residence = excluded.tax_residence, updated_at = now();
  update cw_prod.family_members set full_name = p_data ->> 'full_name', birth_date = (p_data ->> 'birth_date')::date
   where client_id = p_client and is_primary;
  if p_address is not null then
    select id into v_addr from cw_prod.addresses where client_id = p_client and kind = 'HOME' order by created_at limit 1;
    if v_addr is null then
      insert into cw_prod.addresses (client_id, kind, country, postal_code, state, city, district, street, number, complement)
      values (p_client, 'HOME', coalesce(p_address ->> 'country', 'BR'), p_address ->> 'postal_code', p_address ->> 'state',
              p_address ->> 'city', p_address ->> 'district', p_address ->> 'street', p_address ->> 'number', p_address ->> 'complement');
    else
      update cw_prod.addresses set country = coalesce(p_address ->> 'country', 'BR'), postal_code = p_address ->> 'postal_code',
        state = p_address ->> 'state', city = p_address ->> 'city', district = p_address ->> 'district',
        street = p_address ->> 'street', number = p_address ->> 'number', complement = p_address ->> 'complement', updated_at = now()
       where id = v_addr;
    end if;
  end if;
end $$;

-- ---------------------------------------------------------------- legal entities (holdings, operating companies, offshore)
create table cw_prod.legal_entities (
  id          uuid primary key default gen_random_uuid(),
  client_id   uuid not null references cw_prod.clients (id) on delete cascade,
  name        text not null check (length(name) between 1 and 200),
  kind        text not null check (kind in ('HOLDING', 'OPERATING', 'OFFSHORE', 'TRUST', 'FUND')),
  cnpj        char(14) check (cnpj ~ '^[0-9]{14}$'),
  country     char(2) not null default 'BR' check (country ~ '^[A-Z]{2}$'),
  currency    char(3) not null default 'BRL' check (currency in ('BRL', 'USD', 'EUR')),
  book_value  numeric(18,2) check (book_value >= 0),          -- equity value of the quotas (for ITCMD on donations)
  notes       text check (length(notes) <= 1000),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  archived_at timestamptz,
  archived_by uuid,
  unique (id, client_id)
);
-- Who holds the entity: full ownership, bare ownership (nua-propriedade) or usufruct (usufruto) per family member.
create table cw_prod.entity_ownership (
  entity_id     uuid not null,
  client_id     uuid not null,
  member_id     uuid not null,
  ownership_pct numeric(7,4) not null check (ownership_pct > 0 and ownership_pct <= 100),
  ownership_right text not null default 'FULL' check (ownership_right in ('FULL', 'BARE', 'USUFRUCT')),
  primary key (entity_id, member_id, ownership_right),
  foreign key (entity_id, client_id) references cw_prod.legal_entities (id, client_id) on delete cascade,
  foreign key (member_id, client_id) references cw_prod.family_members (id, client_id) on delete cascade
);

-- ---------------------------------------------------------------- assets and accounts: currency, country, entity, marital nature
alter table cw_prod.assets
  add column currency char(3) not null default 'BRL' check (currency in ('BRL', 'USD', 'EUR')),
  add column country char(2) not null default 'BR' check (country ~ '^[A-Z]{2}$'),
  add column marital_nature text not null default 'COMMON' check (marital_nature in ('COMMON', 'PRIVATE')), -- bem comum ou particular
  add column owner_entity_id uuid,
  add foreign key (owner_entity_id, client_id) references cw_prod.legal_entities (id, client_id);

alter table cw_prod.financial_accounts drop constraint financial_accounts_currency_check;
alter table cw_prod.financial_accounts
  add constraint financial_accounts_currency_check check (currency in ('BRL', 'USD', 'EUR')),
  add column balance numeric(18,2) check (balance >= 0),
  add column balance_date date check (balance_date <= current_date),
  add column country char(2) not null default 'BR' check (country ~ '^[A-Z]{2}$'),
  add column joint boolean not null default false,             -- conta conjunta
  add column owner_entity_id uuid,
  add foreign key (owner_entity_id, client_id) references cw_prod.legal_entities (id, client_id);

-- ---------------------------------------------------------------- private pension (PGBL / VGBL)
create table cw_prod.pension_plans (
  id                   uuid primary key default gen_random_uuid(),
  client_id            uuid not null references cw_prod.clients (id) on delete cascade,
  holder_member_id     uuid not null,
  kind                 text not null check (kind in ('PGBL', 'VGBL')),
  provider             text check (length(provider) <= 120),
  balance              numeric(18,2) not null default 0 check (balance >= 0),
  balance_date         date check (balance_date <= current_date),
  contributions_total  numeric(18,2) check (contributions_total >= 0),   -- VGBL: tax applies only to earnings
  monthly_contribution numeric(18,2) not null default 0 check (monthly_contribution >= 0),
  tax_regime           text not null default 'REGRESSIVE' check (tax_regime in ('REGRESSIVE', 'PROGRESSIVE', 'UNDECIDED')),
  first_contribution   date,
  beneficiaries        jsonb not null default '[]' check (jsonb_typeof(beneficiaries) = 'array' and jsonb_array_length(beneficiaries) <= 20),
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  archived_at          timestamptz,
  archived_by          uuid,
  foreign key (holder_member_id, client_id) references cw_prod.family_members (id, client_id)
);

-- ---------------------------------------------------------------- personal insurance (life, disability, critical illness, income)
create table cw_prod.personal_insurances (
  id                uuid primary key default gen_random_uuid(),
  client_id         uuid not null references cw_prod.clients (id) on delete cascade,
  insured_member_id uuid not null,
  kind              text not null check (kind in ('LIFE', 'DISABILITY', 'CRITICAL_ILLNESS', 'TEMP_INCAPACITY', 'FUNERAL', 'OTHER')),
  insurer           text check (length(insurer) <= 120),
  coverage          numeric(18,2) not null check (coverage >= 0),   -- capital segurado (DIT: valor da diária)
  monthly_premium   numeric(18,2) check (monthly_premium >= 0),
  term              text not null default 'TERM' check (term in ('WHOLE_LIFE', 'TERM')),
  end_date          date,
  beneficiaries     jsonb not null default '[]' check (jsonb_typeof(beneficiaries) = 'array' and jsonb_array_length(beneficiaries) <= 20),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  archived_at       timestamptz,
  archived_by       uuid,
  foreign key (insured_member_id, client_id) references cw_prod.family_members (id, client_id)
);

-- ---------------------------------------------------------------- succession profile (one per client)
create table cw_prod.succession_profiles (
  client_id        uuid primary key references cw_prod.clients (id) on delete cascade,
  domicile_uf      char(2) check (domicile_uf ~ '^[A-Z]{2}$'),        -- ITCMD state (defaults to the home address)
  has_will         boolean not null default false,
  will_notes       text check (length(will_notes) <= 2000),
  donations_notes  text check (length(donations_notes) <= 2000),     -- prior donations, advance of inheritance, usufruct
  inventory_kind   text not null default 'EXTRAJUDICIAL' check (inventory_kind in ('EXTRAJUDICIAL', 'JUDICIAL')),
  legal_fee_pct    numeric(5,2) not null default 5 check (legal_fee_pct between 0 and 20),
  court_costs_pct  numeric(5,2) not null default 1.5 check (court_costs_pct between 0 and 10),
  other_costs      numeric(18,2) not null default 0 check (other_costs >= 0),
  updated_at       timestamptz not null default now()
);

do $$
declare t text;
begin
  foreach t in array array['legal_entities', 'entity_ownership', 'pension_plans', 'personal_insurances', 'succession_profiles'] loop
    execute format('alter table cw_prod.%I enable row level security', t);
    execute format('alter table cw_prod.%I force row level security', t);
    execute format('create policy %I on cw_prod.%I for select to authenticated using ((select cw_prod_private.can_access_client(client_id)))', t || '_read', t);
    execute format('revoke all on cw_prod.%I from public, anon, authenticated', t);
    execute format('grant select on cw_prod.%I to authenticated', t);
    execute format('grant all on cw_prod.%I to service_role', t);
    execute format('create trigger t_audit after insert or update or delete on cw_prod.%I for each row execute function cw_prod_private.audit_row()', t);
  end loop;
end $$;

-- ---------------------------------------------------------------- registry RPCs
create function cw_prod.registry_set_account_details(p_account uuid, p_data jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare v_client uuid;
begin
  select client_id into v_client from cw_prod.financial_accounts where id = p_account and archived_at is null;
  perform cw_prod_private.require_client(v_client);
  if (p_data ->> 'entity_id') is not null and not exists (select 1 from cw_prod.legal_entities where id = (p_data ->> 'entity_id')::uuid and client_id = v_client) then
    perform cw_prod_private.deny();
  end if;
  update cw_prod.financial_accounts
     set balance = nullif(p_data ->> 'balance', '')::numeric, balance_date = nullif(p_data ->> 'balance_date', '')::date,
         currency = coalesce(nullif(p_data ->> 'currency', ''), 'BRL'), country = coalesce(nullif(p_data ->> 'country', ''), 'BR'),
         joint = coalesce((p_data ->> 'joint')::boolean, false), owner_entity_id = nullif(p_data ->> 'entity_id', '')::uuid, updated_at = now()
   where id = p_account;
end $$;

create function cw_prod.registry_set_asset_details(p_asset uuid, p_data jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare v_client uuid;
begin
  select client_id into v_client from cw_prod.assets where id = p_asset and archived_at is null;
  perform cw_prod_private.require_client(v_client);
  if (p_data ->> 'entity_id') is not null and not exists (select 1 from cw_prod.legal_entities where id = (p_data ->> 'entity_id')::uuid and client_id = v_client) then
    perform cw_prod_private.deny();
  end if;
  update cw_prod.assets
     set currency = coalesce(nullif(p_data ->> 'currency', ''), 'BRL'), country = coalesce(nullif(p_data ->> 'country', ''), 'BR'),
         marital_nature = coalesce(nullif(p_data ->> 'marital_nature', ''), 'COMMON'), owner_entity_id = nullif(p_data ->> 'entity_id', '')::uuid,
         updated_at = now()
   where id = p_asset;
end $$;

-- p_owners: [{"member_id": "...", "pct": "60", "right": "FULL" | "BARE" | "USUFRUCT"}]; per right the total is ≤ 100%.
create function cw_prod.registry_upsert_entity(p_client uuid, p_entity uuid, p_data jsonb, p_owners jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid := p_entity;
begin
  perform cw_prod_private.require_client(p_client);
  if v_id is null then
    insert into cw_prod.legal_entities (client_id, name, kind, cnpj, country, currency, book_value, notes)
    values (p_client, btrim(p_data ->> 'name'), p_data ->> 'kind', nullif(p_data ->> 'cnpj', ''), coalesce(nullif(p_data ->> 'country', ''), 'BR'),
            coalesce(nullif(p_data ->> 'currency', ''), 'BRL'), nullif(p_data ->> 'book_value', '')::numeric, nullif(btrim(p_data ->> 'notes'), ''))
    returning id into v_id;
  else
    update cw_prod.legal_entities set name = btrim(p_data ->> 'name'), kind = p_data ->> 'kind', cnpj = nullif(p_data ->> 'cnpj', ''),
      country = coalesce(nullif(p_data ->> 'country', ''), 'BR'), currency = coalesce(nullif(p_data ->> 'currency', ''), 'BRL'),
      book_value = nullif(p_data ->> 'book_value', '')::numeric, notes = nullif(btrim(p_data ->> 'notes'), ''), updated_at = now()
     where id = v_id and client_id = p_client and archived_at is null;
    if not found then perform cw_prod_private.deny(); end if;
  end if;
  if p_owners is not null then
    if jsonb_typeof(p_owners) <> 'array' or jsonb_array_length(p_owners) > 40 then raise exception 'invalid owners' using errcode = '22023'; end if;
    delete from cw_prod.entity_ownership where entity_id = v_id;
    insert into cw_prod.entity_ownership (entity_id, client_id, member_id, ownership_pct, ownership_right)
    select v_id, p_client, (o ->> 'member_id')::uuid, (o ->> 'pct')::numeric, coalesce(o ->> 'right', 'FULL') from jsonb_array_elements(p_owners) o;
    if exists (select 1 from cw_prod.entity_ownership where entity_id = v_id group by ownership_right having sum(ownership_pct) > 100) then
      raise exception 'ownership above 100' using errcode = '22023';
    end if;
  end if;
  return v_id;
end $$;

create function cw_prod.registry_upsert_pension(p_client uuid, p_id uuid, p_data jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid := p_id;
begin
  perform cw_prod_private.require_client(p_client);
  if v_id is null then
    insert into cw_prod.pension_plans (client_id, holder_member_id, kind, provider, balance, balance_date, contributions_total, monthly_contribution,
                                     tax_regime, first_contribution, beneficiaries)
    values (p_client, (p_data ->> 'holder_member_id')::uuid, p_data ->> 'kind', nullif(btrim(p_data ->> 'provider'), ''), (p_data ->> 'balance')::numeric,
            nullif(p_data ->> 'balance_date', '')::date, nullif(p_data ->> 'contributions_total', '')::numeric,
            coalesce(nullif(p_data ->> 'monthly_contribution', '')::numeric, 0), coalesce(nullif(p_data ->> 'tax_regime', ''), 'REGRESSIVE'),
            nullif(p_data ->> 'first_contribution', '')::date, coalesce(p_data -> 'beneficiaries', '[]'::jsonb))
    returning id into v_id;
  else
    update cw_prod.pension_plans set holder_member_id = (p_data ->> 'holder_member_id')::uuid, kind = p_data ->> 'kind',
      provider = nullif(btrim(p_data ->> 'provider'), ''), balance = (p_data ->> 'balance')::numeric, balance_date = nullif(p_data ->> 'balance_date', '')::date,
      contributions_total = nullif(p_data ->> 'contributions_total', '')::numeric, monthly_contribution = coalesce(nullif(p_data ->> 'monthly_contribution', '')::numeric, 0),
      tax_regime = coalesce(nullif(p_data ->> 'tax_regime', ''), 'REGRESSIVE'), first_contribution = nullif(p_data ->> 'first_contribution', '')::date,
      beneficiaries = coalesce(p_data -> 'beneficiaries', '[]'::jsonb), updated_at = now()
     where id = v_id and client_id = p_client and archived_at is null;
    if not found then perform cw_prod_private.deny(); end if;
  end if;
  return v_id;
end $$;

create function cw_prod.registry_upsert_personal_insurance(p_client uuid, p_id uuid, p_data jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid := p_id;
begin
  perform cw_prod_private.require_client(p_client);
  if v_id is null then
    insert into cw_prod.personal_insurances (client_id, insured_member_id, kind, insurer, coverage, monthly_premium, term, end_date, beneficiaries)
    values (p_client, (p_data ->> 'insured_member_id')::uuid, p_data ->> 'kind', nullif(btrim(p_data ->> 'insurer'), ''), (p_data ->> 'coverage')::numeric,
            nullif(p_data ->> 'monthly_premium', '')::numeric, coalesce(nullif(p_data ->> 'term', ''), 'TERM'), nullif(p_data ->> 'end_date', '')::date,
            coalesce(p_data -> 'beneficiaries', '[]'::jsonb))
    returning id into v_id;
  else
    update cw_prod.personal_insurances set insured_member_id = (p_data ->> 'insured_member_id')::uuid, kind = p_data ->> 'kind',
      insurer = nullif(btrim(p_data ->> 'insurer'), ''), coverage = (p_data ->> 'coverage')::numeric, monthly_premium = nullif(p_data ->> 'monthly_premium', '')::numeric,
      term = coalesce(nullif(p_data ->> 'term', ''), 'TERM'), end_date = nullif(p_data ->> 'end_date', '')::date,
      beneficiaries = coalesce(p_data -> 'beneficiaries', '[]'::jsonb), updated_at = now()
     where id = v_id and client_id = p_client and archived_at is null;
    if not found then perform cw_prod_private.deny(); end if;
  end if;
  return v_id;
end $$;

create function cw_prod.succession_profile_save(p_client uuid, p_data jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  perform cw_prod_private.require_client(p_client);
  insert into cw_prod.succession_profiles as s (client_id, domicile_uf, has_will, will_notes, donations_notes, inventory_kind, legal_fee_pct, court_costs_pct, other_costs)
  values (p_client, nullif(p_data ->> 'domicile_uf', ''), coalesce((p_data ->> 'has_will')::boolean, false), nullif(btrim(p_data ->> 'will_notes'), ''),
          nullif(btrim(p_data ->> 'donations_notes'), ''), coalesce(nullif(p_data ->> 'inventory_kind', ''), 'EXTRAJUDICIAL'),
          coalesce(nullif(p_data ->> 'legal_fee_pct', '')::numeric, 5), coalesce(nullif(p_data ->> 'court_costs_pct', '')::numeric, 1.5),
          coalesce(nullif(p_data ->> 'other_costs', '')::numeric, 0))
  on conflict (client_id) do update set domicile_uf = excluded.domicile_uf, has_will = excluded.has_will, will_notes = excluded.will_notes,
    donations_notes = excluded.donations_notes, inventory_kind = excluded.inventory_kind, legal_fee_pct = excluded.legal_fee_pct,
    court_costs_pct = excluded.court_costs_pct, other_costs = excluded.other_costs, updated_at = now();
end $$;

-- Archive for the new registry records (same soft-delete rule as registry_archive).
create function cw_prod.registry_archive_wealth(p_entity text, p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare v_client uuid;
begin
  if p_entity = 'entity' then
    select client_id into v_client from cw_prod.legal_entities where id = p_id and archived_at is null;
    perform cw_prod_private.require_client(v_client);
    if exists (select 1 from cw_prod.assets where owner_entity_id = p_id and archived_at is null)
       or exists (select 1 from cw_prod.financial_accounts where owner_entity_id = p_id and archived_at is null) then
      raise exception 'entity holds assets' using errcode = '23503';
    end if;
    update cw_prod.legal_entities set archived_at = now(), archived_by = auth.uid() where id = p_id;
  elsif p_entity = 'pension' then
    select client_id into v_client from cw_prod.pension_plans where id = p_id and archived_at is null;
    perform cw_prod_private.require_client(v_client);
    update cw_prod.pension_plans set archived_at = now(), archived_by = auth.uid() where id = p_id;
  elsif p_entity = 'personal_insurance' then
    select client_id into v_client from cw_prod.personal_insurances where id = p_id and archived_at is null;
    perform cw_prod_private.require_client(v_client);
    update cw_prod.personal_insurances set archived_at = now(), archived_by = auth.uid() where id = p_id;
  else
    perform cw_prod_private.deny();
  end if;
end $$;

-- ---------------------------------------------------------------- FX rates (BCB PTAX, fetched by the server)
create table cw_prod.fx_rates (
  currency   char(3) not null check (currency in ('USD', 'EUR')),
  rate_date  date not null,
  rate       numeric(14,6) not null check (rate > 0),     -- BRL per unit (PTAX venda, boletim de fechamento)
  source     text not null default 'BCB_PTAX' check (length(source) <= 40),
  fetched_at timestamptz not null default now(),
  primary key (currency, rate_date)
);
alter table cw_prod.fx_rates enable row level security, force row level security;
create policy fx_rates_read on cw_prod.fx_rates for select to authenticated using (true);
revoke all on cw_prod.fx_rates from public, anon, authenticated;
grant select on cw_prod.fx_rates to authenticated;
grant all on cw_prod.fx_rates to service_role;

create function cw_prod.fx_rate_store(p_currency text, p_date date, p_rate numeric) returns void
language sql security definer set search_path = '' as $$
  insert into cw_prod.fx_rates (currency, rate_date, rate) values (p_currency, p_date, p_rate)
  on conflict (currency, rate_date) do update set rate = excluded.rate, fetched_at = now()
$$;

-- ---------------------------------------------------------------- ITCMD rules per state (admin publishes, like tax rules)
create table cw_prod.itcmd_rules (
  id           uuid primary key default gen_random_uuid(),
  uf           char(2) not null check (uf ~ '^[A-Z]{2}$'),
  version      smallint not null check (version > 0),
  -- {"mode": "MARGINAL" | "FLAT_BY_BRACKET", "brackets": [{"up_to_cents": "…" | null, "rate": "0.04"}], "pension_taxed": false}
  rules        jsonb not null check (jsonb_typeof(rules) = 'object' and length(rules::text) <= 4000),
  source_reference text not null check (length(source_reference) between 10 and 1000),
  notes        text check (length(notes) <= 1000),
  created_by   uuid,
  created_at   timestamptz not null default now(),
  published_at timestamptz,
  published_by uuid,
  unique (uf, version)
);
alter table cw_prod.itcmd_rules enable row level security, force row level security;
create policy itcmd_rules_read on cw_prod.itcmd_rules for select to authenticated using ((select cw_prod_private.is_staff()));
revoke all on cw_prod.itcmd_rules from public, anon, authenticated;
grant select on cw_prod.itcmd_rules to authenticated;
grant all on cw_prod.itcmd_rules to service_role;
create trigger t_audit after insert or update or delete on cw_prod.itcmd_rules for each row execute function cw_prod_private.audit_row();

create function cw_prod.itcmd_rule_save(p_uf text, p_rules jsonb, p_source text, p_notes text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if not cw_prod_private.is_admin() then perform cw_prod_private.deny(); end if;
  insert into cw_prod.itcmd_rules (uf, version, rules, source_reference, notes, created_by)
  values (upper(p_uf), coalesce((select max(version) from cw_prod.itcmd_rules where uf = upper(p_uf)), 0) + 1, p_rules, p_source, p_notes, auth.uid())
  returning id into v_id;
  return v_id;
end $$;

create function cw_prod.itcmd_rule_publish(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_prod_private.is_admin() then perform cw_prod_private.deny(); end if;
  update cw_prod.itcmd_rules set published_at = now(), published_by = auth.uid() where id = p_id and published_at is null;
  if not found then perform cw_prod_private.deny(); end if;
end $$;

-- ---------------------------------------------------------------- meetings: Google Meet link
alter table cw_prod.crm_events add column meeting_url text check (meeting_url ~ '^https://' and length(meeting_url) <= 500);
create function cw_prod.crm_event_set_meeting_url(p_id uuid, p_url text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  update cw_prod.crm_events set meeting_url = p_url, location = coalesce(location, p_url), updated_at = now()
   where id = p_id and owner_id = auth.uid();
  if not found then perform cw_prod_private.deny(); end if;
end $$;

-- ---------------------------------------------------------------- analyses → CRM funnel
-- CRM contact of a portfolio client (created on first use, linked to the client) so opportunities can be tracked.
create function cw_prod.crm_contact_for_client(p_client uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_name text; v_email text;
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  perform cw_prod_private.require_client(p_client);
  select id into v_id from cw_prod.crm_contacts where client_id = p_client order by created_at limit 1;
  if v_id is not null then return v_id; end if;
  select coalesce(nullif(p.full_name, ''), c.display_name), p.email into v_name, v_email
    from cw_prod.clients c left join cw_prod.client_personal_data p on p.client_id = c.id where c.id = p_client;
  insert into cw_prod.crm_contacts (kind, full_name, email, source, owner_id, status, client_id, created_by)
  values ('PERSON', left(v_name, 200), v_email, 'Carteira', auth.uid(), 'CLIENT', p_client, auth.uid())
  returning id into v_id;
  return v_id;
end $$;

-- Opportunity found by an analysis (insurance, pension…). Idempotent per client and title while it is open.
create function cw_prod.crm_analysis_opportunity(p_client uuid, p_title text, p_source text, p_amount numeric, p_next_action text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_contact uuid; v_id uuid;
begin
  v_contact := cw_prod.crm_contact_for_client(p_client);
  select id into v_id from cw_prod.crm_opportunities
   where contact_id = v_contact and title = btrim(p_title) and stage not in ('WON', 'LOST');
  if v_id is not null then return v_id; end if;
  insert into cw_prod.crm_opportunities (contact_id, client_id, owner_id, title, source, estimated_assets, next_action, next_action_date, created_by)
  values (v_contact, p_client, auth.uid(), left(btrim(p_title), 160), left(p_source, 80), p_amount, left(p_next_action, 300), current_date + 7, auth.uid())
  returning id into v_id;
  return v_id;
end $$;

-- ---------------------------------------------------------------- tax: 2026 is the reference; drop the never-published 2025 draft
-- The guard forbids deletes in general; it is lifted only for this one statement (never-published draft, no calculations).
alter table cw_prod.tax_rule_sets disable trigger t_rule_set_guard;
delete from cw_prod.tax_rule_sets r
 where r.tax_year = 2025 and r.published_at is null
   and not exists (select 1 from cw_prod.pgbl_calculations c where c.rule_set_id = r.id);
alter table cw_prod.tax_rule_sets enable trigger t_rule_set_guard;

revoke all on function
  cw_prod.registry_set_account_details(uuid, jsonb), cw_prod.registry_set_asset_details(uuid, jsonb),
  cw_prod.registry_upsert_entity(uuid, uuid, jsonb, jsonb), cw_prod.registry_upsert_pension(uuid, uuid, jsonb),
  cw_prod.registry_upsert_personal_insurance(uuid, uuid, jsonb), cw_prod.succession_profile_save(uuid, jsonb),
  cw_prod.registry_archive_wealth(text, uuid), cw_prod.fx_rate_store(text, date, numeric),
  cw_prod.itcmd_rule_save(text, jsonb, text, text), cw_prod.itcmd_rule_publish(uuid),
  cw_prod.crm_event_set_meeting_url(uuid, text), cw_prod.crm_contact_for_client(uuid),
  cw_prod.crm_analysis_opportunity(uuid, text, text, numeric, text)
  from public, anon, authenticated;
grant execute on function
  cw_prod.registry_set_account_details(uuid, jsonb), cw_prod.registry_set_asset_details(uuid, jsonb),
  cw_prod.registry_upsert_entity(uuid, uuid, jsonb, jsonb), cw_prod.registry_upsert_pension(uuid, uuid, jsonb),
  cw_prod.registry_upsert_personal_insurance(uuid, uuid, jsonb), cw_prod.succession_profile_save(uuid, jsonb),
  cw_prod.registry_archive_wealth(text, uuid), cw_prod.itcmd_rule_save(text, jsonb, text, text), cw_prod.itcmd_rule_publish(uuid),
  cw_prod.crm_event_set_meeting_url(uuid, text), cw_prod.crm_contact_for_client(uuid),
  cw_prod.crm_analysis_opportunity(uuid, text, text, numeric, text) to authenticated;
grant execute on function cw_prod.fx_rate_store(text, date, numeric) to service_role;

commit;

